const physicsTopics = [{"grade": 7, "name": "Физические величины и измерения", "section": "Введение", "intro": "Измерить величину — значит сравнить её с единицей. Записывай не только число, но и единицу, а перед вычислениями переводи данные в согласованную систему.", "rules": ["СИ: метр, килограмм, секунда.", "Цена деления = разность соседних подписанных значений / число промежутков.", "При переводе площади и объёма коэффициент тоже возводят в степень."], "mistake": "В 1 м² не 100, а 10 000 см².", "problems": [{"question": "Переведи 250 см в метры.", "answer": 2.5, "unit": "м", "hint": "В метре 100 сантиметров.", "steps": ["250 : 100 = 2,5 м."]}, {"question": "Между отметками 10 и 30 мл на мензурке 10 равных промежутков. Найди цену деления в мл.", "answer": 2, "unit": "мл", "hint": "Дели разность, а не конечное значение.", "steps": ["(30 − 10) / 10 = 2 мл."]}, {"question": "Объём кубика 8 см³. Найди его объём в м³.", "answer": 8e-06, "unit": "м³", "hint": "1 см = 0,01 м, коэффициент для объёма кубический.", "steps": ["1 см³ = 10⁻⁶ м³.", "8 см³ = 8 × 10⁻⁶ м³."]}]}, {"grade": 7, "name": "Равномерное движение", "section": "Механика", "intro": "При равномерном движении тело за равные промежутки времени проходит равные пути. Формула связывает путь, скорость и время.", "rules": ["v = s/t.", "s = vt; t = s/v.", "1 м/с = 3,6 км/ч."], "mistake": "Не смешивай часы с секундами в одной подстановке.", "problems": [{"question": "Пешеход прошёл 600 м за 300 с. Найди скорость.", "answer": 2, "unit": "м/с", "hint": "Раздели путь на время.", "steps": ["v = 600/300 = 2 м/с."]}, {"question": "Автомобиль едет 72 км/ч. Какой путь он пройдёт за 15 с?", "answer": 300, "unit": "м", "hint": "Переведи скорость в м/с.", "steps": ["72/3,6 = 20 м/с.", "s = 20 × 15 = 300 м."]}, {"question": "Поезд длиной 180 м полностью проходит мост длиной 420 м за 30 с. Найди скорость поезда.", "answer": 20, "unit": "м/с", "hint": "Для полного прохождения нужно учесть длину поезда.", "steps": ["Путь переднего конца: 180 + 420 = 600 м.", "v = 600/30 = 20 м/с."]}]}, {"grade": 7, "name": "Масса и плотность", "section": "Механика", "intro": "Плотность показывает массу единицы объёма вещества. Масса относится ко всему телу, плотность характеризует материал при заданных условиях.", "rules": ["ρ = m/V.", "m = ρV.", "1 г/см³ = 1000 кг/м³."], "mistake": "Полость внутри тела уменьшает среднюю плотность всего тела.", "problems": [{"question": "Масса тела 540 г, объём 200 см³. Найди плотность в кг/м³.", "answer": 2700, "unit": "кг/м³", "hint": "Сначала можно найти плотность в г/см³.", "steps": ["540/200 = 2,7 г/см³.", "Это 2700 кг/м³."]}, {"question": "Объём алюминиевой детали 0,002 м³, плотность 2700 кг/м³. Найди массу.", "answer": 5.4, "unit": "кг", "hint": "m = ρV.", "steps": ["m = 2700 × 0,002 = 5,4 кг."]}, {"question": "Стальная деталь массой 780 г имеет внешний объём 150 см³. Плотность стали 7,8 г/см³. Найди объём полости.", "answer": 50, "unit": "см³", "hint": "Найди объём самой стали.", "steps": ["V стали = 780/7,8 = 100 см³.", "V полости = 150 − 100 = 50 см³."]}]}, {"grade": 7, "name": "Силы и закон Гука", "section": "Механика", "intro": "Сила описывает взаимодействие тел. Для малых упругих деформаций сила упругости пропорциональна удлинению пружины.", "rules": ["F тяжести = mg.", "F упругости = kx.", "Здесь в задачах g = 10 Н/кг, если не указано другое."], "mistake": "Закон Гука применяют в пределах упругой деформации.", "problems": [{"question": "Масса груза 3 кг. Найди силу тяжести при g = 10 Н/кг.", "answer": 30, "unit": "Н", "hint": "Умножь массу на g.", "steps": ["F = 3 × 10 = 30 Н."]}, {"question": "Жёсткость пружины 200 Н/м, удлинение 4 см. Найди силу упругости.", "answer": 8, "unit": "Н", "hint": "Переведи удлинение в метры.", "steps": ["x = 0,04 м.", "F = 200 × 0,04 = 8 Н."]}, {"question": "Две пружины одинаковой жёсткости 100 Н/м соединены последовательно. Груз тянет каждую силой 10 Н. Найди суммарное удлинение.", "answer": 0.2, "unit": "м", "hint": "Удлинения складываются.", "steps": ["Каждая пружина удлинится на 10/100 = 0,1 м.", "Суммарно 0,2 м."]}]}, {"grade": 7, "name": "Давление твёрдых тел", "section": "Давление", "intro": "Давление зависит и от силы, и от площади опоры. Одна и та же сила на меньшей площади создаёт большее давление.", "rules": ["p = F/S.", "1 Па = 1 Н/м².", "Площадь в формуле выражай в м²."], "mistake": "В формулу входит сила, действующая перпендикулярно поверхности.", "problems": [{"question": "Сила 100 Н действует на площадь 0,5 м². Найди давление.", "answer": 200, "unit": "Па", "hint": "Раздели силу на площадь.", "steps": ["p = 100/0,5 = 200 Па."]}, {"question": "Тело массой 20 кг опирается на площадь 100 см². Найди давление при g = 10 Н/кг.", "answer": 20000, "unit": "Па", "hint": "100 см² = 0,01 м².", "steps": ["F = 20 × 10 = 200 Н.", "p = 200/0,01 = 20000 Па."]}, {"question": "Куб массой 8 кг имеет ребро 20 см. На него поставили груз 12 кг. Найди давление куба на пол при g = 10 Н/кг.", "answer": 5000, "unit": "Па", "hint": "Сложи массы, площадь опоры — одна грань.", "steps": ["F = (8 + 12) × 10 = 200 Н.", "S = 0,2² = 0,04 м².", "p = 5000 Па."]}]}, {"grade": 7, "name": "Гидростатическое давление", "section": "Давление", "intro": "В покоящейся жидкости давление растёт с глубиной. Добавочное давление столба жидкости зависит от плотности, глубины и g, но не от формы сосуда.", "rules": ["p = ρgh — избыточное давление.", "Полное давление = атмосферное + ρgh.", "Для воды используй ρ = 1000 кг/м³."], "mistake": "Избыточное и абсолютное давление — разные величины.", "problems": [{"question": "Найди избыточное давление воды на глубине 2 м при g = 10 Н/кг.", "answer": 20000, "unit": "Па", "hint": "p = ρgh.", "steps": ["p = 1000 × 10 × 2 = 20000 Па."]}, {"question": "В масле плотностью 800 кг/м³ давление столба равно 12000 Па. Найди высоту столба при g = 10 Н/кг.", "answer": 1.5, "unit": "м", "hint": "Вырази h из формулы давления.", "steps": ["h = 12000/(800 × 10) = 1,5 м."]}, {"question": "На какой глубине в воде полное давление равно 150 кПа, если атмосферное 100 кПа и g = 10 Н/кг?", "answer": 5, "unit": "м", "hint": "Вычти атмосферное давление.", "steps": ["Избыточное давление 50 кПа = 50000 Па.", "h = 50000/10000 = 5 м."]}]}, {"grade": 7, "name": "Архимедова сила и плавание", "section": "Давление", "intro": "Жидкость выталкивает тело с силой, равной весу вытесненной жидкости. Для плавающего тела выталкивающая сила уравновешивает силу тяжести.", "rules": ["F_A = ρ жидкости × g × V погружённой части.", "При плавании F_A = mg.", "Доля погружения однородного тела = ρ тела / ρ жидкости."], "mistake": "В формулу входит погружённый объём, а не всегда весь объём тела.", "problems": [{"question": "Тело вытеснило 0,003 м³ воды. Найди архимедову силу при g = 10 Н/кг.", "answer": 30, "unit": "Н", "hint": "Плотность воды 1000 кг/м³.", "steps": ["F_A = 1000 × 10 × 0,003 = 30 Н."]}, {"question": "Деревянный куб объёмом 0,01 м³ и плотностью 600 кг/м³ плавает в воде. Найди погружённый объём.", "answer": 0.006, "unit": "м³", "hint": "В воде погружается 60% объёма.", "steps": ["V погр = 600/1000 × 0,01 = 0,006 м³."]}, {"question": "Камень объёмом 0,002 м³ весит в воздухе 50 Н. Найди показание динамометра при полном погружении в воду. g = 10 Н/кг.", "answer": 30, "unit": "Н", "hint": "Натяжение меньше силы тяжести на архимедову силу.", "steps": ["F_A = 1000 × 10 × 0,002 = 20 Н.", "T = 50 − 20 = 30 Н."]}]}, {"grade": 7, "name": "Работа, мощность и рычаг", "section": "Энергия", "intro": "Работа силы показывает передачу энергии при перемещении. Простой механизм может давать выигрыш в силе за счёт проигрыша в расстоянии.", "rules": ["A = Fs для силы вдоль перемещения.", "P = A/t.", "Равновесие рычага: F₁l₁ = F₂l₂."], "mistake": "Идеальный механизм не даёт выигрыша в работе.", "problems": [{"question": "Сила 20 Н перемещает тело вдоль своего направления на 3 м. Найди работу.", "answer": 60, "unit": "Дж", "hint": "Умножь силу на путь.", "steps": ["A = 20 × 3 = 60 Дж."]}, {"question": "Механизм выполнил работу 1200 Дж за 20 с. Найди мощность.", "answer": 60, "unit": "Вт", "hint": "Мощность — работа в единицу времени.", "steps": ["P = 1200/20 = 60 Вт."]}, {"question": "На плечо рычага 0,2 м действует сила 120 Н. Какую силу нужно приложить к плечу 0,8 м для равновесия?", "answer": 30, "unit": "Н", "hint": "Приравняй моменты.", "steps": ["120 × 0,2 = F × 0,8.", "F = 30 Н."]}]}, {"grade": 8, "name": "Внутренняя энергия и теплопередача", "section": "Тепловые явления", "intro": "Внутренняя энергия связана с движением и взаимодействием частиц вещества. Её изменяют совершением работы и теплопередачей.", "rules": ["Теплопроводность передаёт энергию без переноса вещества.", "Конвекция связана с движением жидкости или газа.", "Излучение возможно и в вакууме."], "mistake": "Температура и внутренняя энергия — разные понятия: масса тела тоже важна.", "problems": [{"question": "Тело получило 200 Дж теплоты, работа не совершалась. На сколько увеличилась внутренняя энергия?", "answer": 200, "unit": "Дж", "hint": "Вся полученная энергия осталась в теле.", "steps": ["ΔU = Q = 200 Дж."]}, {"question": "Тело получило 500 Дж теплоты и отдало окружающим 180 Дж. Работа не совершалась. Найди изменение внутренней энергии.", "answer": 320, "unit": "Дж", "hint": "Сложи передачи энергии со знаками.", "steps": ["ΔU = 500 − 180 = 320 Дж."]}, {"question": "Над газом совершили работу 300 Дж, затем он отдал 120 Дж теплоты. Найди изменение внутренней энергии.", "answer": 180, "unit": "Дж", "hint": "Работа над газом увеличивает U.", "steps": ["ΔU = 300 − 120 = 180 Дж."]}]}, {"grade": 8, "name": "Нагревание и теплоёмкость", "section": "Тепловые явления", "intro": "Удельная теплоёмкость показывает, сколько энергии нужно для нагревания одного килограмма вещества на один градус.", "rules": ["Q = cmΔT.", "Разность температур в °C численно равна разности в K.", "Формула нагревания не описывает фазовый переход."], "mistake": "При плавлении энергия может поступать без роста температуры.", "problems": [{"question": "Нагревают 1 кг воды на 10 °C. c = 4200 Дж/(кг·°C). Найди количество теплоты.", "answer": 42000, "unit": "Дж", "hint": "Q = cmΔT.", "steps": ["Q = 4200 × 1 × 10 = 42000 Дж."]}, {"question": "Металлическое тело массой 2 кг получило 18000 Дж и нагрелось на 20 °C. Найди удельную теплоёмкость.", "answer": 450, "unit": "Дж/(кг·К)", "hint": "Вырази c.", "steps": ["c = 18000/(2 × 20) = 450 Дж/(кг·К)."]}, {"question": "Нагреватель мощностью 500 Вт без потерь нагревает 0,5 кг воды на 20 °C. c = 4200 Дж/(кг·°C). За какое время?", "answer": 84, "unit": "с", "hint": "Сначала Q, затем t = Q/P.", "steps": ["Q = 4200 × 0,5 × 20 = 42000 Дж.", "t = 42000/500 = 84 с."]}]}, {"grade": 8, "name": "Плавление и парообразование", "section": "Тепловые явления", "intro": "Во время фазового перехода энергия идёт на изменение структуры вещества. При постоянном давлении чистое вещество плавится или кипит при определённой температуре.", "rules": ["Q плавления = λm.", "Q парообразования = Lm.", "Нагревание и переход считают отдельными этапами."], "mistake": "Удельная теплота плавления и теплоёмкость имеют разные единицы.", "problems": [{"question": "Расплавили 0,2 кг льда при 0 °C. λ = 340000 Дж/кг. Найди теплоту.", "answer": 68000, "unit": "Дж", "hint": "Температура льда уже равна температуре плавления.", "steps": ["Q = 340000 × 0,2 = 68000 Дж."]}, {"question": "На испарение воды при температуре кипения затрачено 460000 Дж. L = 2300000 Дж/кг. Найди массу пара.", "answer": 0.2, "unit": "кг", "hint": "m = Q/L.", "steps": ["m = 460000/2300000 = 0,2 кг."]}, {"question": "Нужно расплавить 0,1 кг льда при 0 °C и нагреть воду до 10 °C. λ = 340000 Дж/кг, c = 4200 Дж/(кг·°C). Найди полную теплоту.", "answer": 38200, "unit": "Дж", "hint": "Сложи теплоту плавления и нагревания воды.", "steps": ["Q₁ = 34000 Дж.", "Q₂ = 4200 × 0,1 × 10 = 4200 Дж.", "Q = 38200 Дж."]}]}, {"grade": 8, "name": "Тепловой баланс и КПД", "section": "Тепловые явления", "intro": "В теплоизолированной системе отданная телами энергия равна полученной. КПД показывает долю затраченной энергии, которая стала полезной.", "rules": ["ΣQ = 0 с учётом знаков.", "η = A полезная / E затраченная.", "0 ≤ η ≤ 1."], "mistake": "Температуру смеси нельзя всегда находить простым средним: важны массы и теплоёмкости.", "problems": [{"question": "Полезная энергия 600 Дж, затраченная 1000 Дж. Найди КПД в процентах.", "answer": 60, "unit": "%", "hint": "Раздели полезную энергию на затраченную.", "steps": ["η = 600/1000 = 0,6 = 60%."]}, {"question": "Смешали 1 кг воды при 20 °C и 1 кг воды при 60 °C. Потерь нет. Найди температуру смеси.", "answer": 40, "unit": "°C", "hint": "Массы и теплоёмкости одинаковы.", "steps": ["T = (20 + 60)/2 = 40 °C."]}, {"question": "Смешали 2 кг воды при 20 °C и 1 кг воды при 80 °C. Потерь нет. Найди температуру смеси.", "answer": 40, "unit": "°C", "hint": "Используй средневзвешенное по массам.", "steps": ["T = (2 × 20 + 1 × 80)/3 = 40 °C."]}]}, {"grade": 8, "name": "Заряд, ток и напряжение", "section": "Электричество", "intro": "Сила тока показывает заряд, проходящий через сечение проводника за единицу времени. Напряжение — работа электрического поля по перемещению единичного заряда.", "rules": ["I = q/t.", "U = A/q.", "1 А = 1 Кл/с; 1 В = 1 Дж/Кл."], "mistake": "Электроны движутся противоположно условному направлению тока.", "problems": [{"question": "За 5 с прошёл заряд 10 Кл. Найди силу тока.", "answer": 2, "unit": "А", "hint": "I = q/t.", "steps": ["I = 10/5 = 2 А."]}, {"question": "Поле совершило работу 120 Дж при переносе заряда 10 Кл. Найди напряжение.", "answer": 12, "unit": "В", "hint": "Раздели работу на заряд.", "steps": ["U = 120/10 = 12 В."]}, {"question": "По проводнику течёт ток 0,2 А в течение 3 минут. Какой заряд прошёл?", "answer": 36, "unit": "Кл", "hint": "Переведи минуты в секунды.", "steps": ["t = 180 с.", "q = 0,2 × 180 = 36 Кл."]}]}, {"grade": 8, "name": "Закон Ома и сопротивление", "section": "Электричество", "intro": "Для участка цепи ток пропорционален напряжению и обратно пропорционален сопротивлению. Сопротивление провода зависит от материала и геометрии.", "rules": ["I = U/R.", "R = ρl/S.", "Для омического проводника при постоянной температуре R постоянно."], "mistake": "Удельное сопротивление ρ не равно сопротивлению всего провода.", "problems": [{"question": "Напряжение 12 В, сопротивление 6 Ом. Найди ток.", "answer": 2, "unit": "А", "hint": "Подставь в закон Ома.", "steps": ["I = 12/6 = 2 А."]}, {"question": "Через резистор течёт ток 0,5 А при напряжении 9 В. Найди сопротивление.", "answer": 18, "unit": "Ом", "hint": "R = U/I.", "steps": ["R = 9/0,5 = 18 Ом."]}, {"question": "Провод имел сопротивление 8 Ом. Его длину увеличили вдвое и площадь сечения тоже вдвое, материал тот же. Найди новое сопротивление.", "answer": 8, "unit": "Ом", "hint": "Учитывай оба изменения в R = ρl/S.", "steps": ["R новое / R старое = 2/2 = 1.", "Сопротивление осталось 8 Ом."]}]}, {"grade": 8, "name": "Соединение проводников", "section": "Электричество", "intro": "При последовательном соединении ток одинаков, а напряжения складываются. При параллельном напряжение одинаково, а токи ветвей складываются.", "rules": ["Последовательно R = R₁ + R₂.", "Параллельно 1/R = 1/R₁ + 1/R₂.", "Два параллельных резистора: R = R₁R₂/(R₁ + R₂)."], "mistake": "Параллельное сопротивление меньше каждого из сопротивлений ветвей.", "problems": [{"question": "Резисторы 4 и 6 Ом соединены последовательно. Найди общее сопротивление.", "answer": 10, "unit": "Ом", "hint": "Сложи сопротивления.", "steps": ["R = 4 + 6 = 10 Ом."]}, {"question": "Резисторы 6 и 3 Ом соединены параллельно. Найди общее сопротивление.", "answer": 2, "unit": "Ом", "hint": "Используй произведение, делённое на сумму.", "steps": ["R = 18/9 = 2 Ом."]}, {"question": "Резистор 2 Ом соединён последовательно с параллельной парой 6 и 3 Ом. Источник 12 В, идеальный. Найди общий ток.", "answer": 3, "unit": "А", "hint": "Сначала сверни параллельную пару.", "steps": ["Параллельная пара: 2 Ом.", "Полное R = 2 + 2 = 4 Ом.", "I = 12/4 = 3 А."]}]}, {"grade": 8, "name": "Работа тока и световые явления", "section": "Электричество и оптика", "intro": "Ток передаёт энергию потребителю. В оптике углы отражения и падения отсчитывают от нормали к поверхности.", "rules": ["P = UI; A = UIt.", "Q = I²Rt для резистора.", "Угол отражения равен углу падения."], "mistake": "Угол к поверхности и угол к нормали дополняют друг друга до 90°.", "problems": [{"question": "Ток 2 А, напряжение 6 В. Найди мощность потребителя.", "answer": 12, "unit": "Вт", "hint": "P = UI.", "steps": ["P = 6 × 2 = 12 Вт."]}, {"question": "Ток 3 А проходит по резистору 4 Ом в течение 10 с. Найди выделившуюся теплоту.", "answer": 360, "unit": "Дж", "hint": "Используй закон Джоуля — Ленца.", "steps": ["Q = 3² × 4 × 10 = 360 Дж."]}, {"question": "Падающий и отражённый лучи образуют угол 100°. Найди угол падения к нормали.", "answer": 50, "unit": "°", "hint": "Нормаль делит угол между лучами пополам.", "steps": ["2α = 100°.", "α = 50°."]}]}, {"grade": 9, "name": "Равноускоренное движение", "section": "Механика", "intro": "При постоянном ускорении скорость меняется равномерно. Путь и перемещение различаются, если направление движения менялось.", "rules": ["v = v₀ + at.", "s = v₀t + at²/2 при движении вдоль оси.", "v² − v₀² = 2as."], "mistake": "Знаки скорости и ускорения зависят от выбора оси.", "problems": [{"question": "Тело стартует из покоя с ускорением 2 м/с². Найди скорость через 4 с.", "answer": 8, "unit": "м/с", "hint": "v₀ = 0.", "steps": ["v = 2 × 4 = 8 м/с."]}, {"question": "Начальная скорость 3 м/с, ускорение 2 м/с², время 5 с. Найди перемещение.", "answer": 40, "unit": "м", "hint": "Сложи оба слагаемых формулы.", "steps": ["s = 3 × 5 + 2 × 25/2 = 40 м."]}, {"question": "Автомобиль со скоростью 20 м/с тормозит с постоянным по модулю ускорением 4 м/с². Найди тормозной путь.", "answer": 50, "unit": "м", "hint": "Конечная скорость равна нулю.", "steps": ["s = v₀²/(2|a|) = 400/8 = 50 м."]}]}, {"grade": 9, "name": "Законы Ньютона и трение", "section": "Механика", "intro": "Ускорение определяется равнодействующей всех сил. Силы взаимодействия из третьего закона приложены к разным телам и не уравновешивают друг друга на одном теле.", "rules": ["ΣF = ma.", "F трения скольжения = μN.", "На горизонтали без других вертикальных сил N = mg."], "mistake": "Не подменяй равнодействующую одной из действующих сил.", "problems": [{"question": "Равнодействующая 12 Н действует на тело 3 кг. Найди ускорение.", "answer": 4, "unit": "м/с²", "hint": "a = F/m.", "steps": ["a = 12/3 = 4 м/с²."]}, {"question": "Тело 5 кг скользит по горизонтали. μ = 0,2, g = 10 м/с². Найди силу трения.", "answer": 10, "unit": "Н", "hint": "Сначала найди нормальную реакцию.", "steps": ["N = 50 Н.", "F = 0,2 × 50 = 10 Н."]}, {"question": "Тело 4 кг тянут горизонтально силой 20 Н. μ = 0,25, g = 10 м/с². Найди ускорение.", "answer": 2.5, "unit": "м/с²", "hint": "Вычти трение из силы тяги.", "steps": ["Трение 0,25 × 40 = 10 Н.", "a = (20 − 10)/4 = 2,5 м/с²."]}]}, {"grade": 9, "name": "Свободное падение и движение по окружности", "section": "Механика", "intro": "Вблизи Земли свободно падающее тело ускоряется вниз. При равномерном движении по окружности модуль скорости постоянен, но её направление меняется.", "rules": ["h = gt²/2 при падении из покоя.", "a центростремительное = v²/r.", "В задачах здесь g = 10 м/с²."], "mistake": "Постоянный модуль скорости не означает нулевого ускорения.", "problems": [{"question": "Тело падает из покоя 2 с. Найди путь без сопротивления воздуха.", "answer": 20, "unit": "м", "hint": "h = gt²/2.", "steps": ["h = 10 × 4/2 = 20 м."]}, {"question": "Скорость 6 м/с, радиус окружности 3 м. Найди центростремительное ускорение.", "answer": 12, "unit": "м/с²", "hint": "a = v²/r.", "steps": ["a = 36/3 = 12 м/с²."]}, {"question": "Тело бросили вертикально вверх со скоростью 20 м/с. Найди максимальную высоту относительно точки броска. g = 10 м/с².", "answer": 20, "unit": "м", "hint": "На вершине скорость равна нулю.", "steps": ["h = v₀²/(2g) = 400/20 = 20 м."]}]}, {"grade": 9, "name": "Импульс и столкновения", "section": "Механика", "intro": "Импульс — векторная величина. В замкнутой системе сумма импульсов сохраняется, даже если кинетическая энергия превращается во внутреннюю.", "rules": ["p = mv.", "Σp до = Σp после в замкнутой системе.", "При слипании тела после удара движутся вместе."], "mistake": "Кинетическая энергия при неупругом ударе обычно не сохраняется.", "problems": [{"question": "Масса 2 кг, скорость 3 м/с. Найди модуль импульса.", "answer": 6, "unit": "кг·м/с", "hint": "p = mv.", "steps": ["p = 2 × 3 = 6 кг·м/с."]}, {"question": "Тело 2 кг движется со скоростью 6 м/с и слипается с неподвижным телом 4 кг. Найди общую скорость.", "answer": 2, "unit": "м/с", "hint": "Общий импульс делится на общую массу.", "steps": ["v = 2 × 6/(2 + 4) = 2 м/с."]}, {"question": "Два тела по 1 кг движутся навстречу со скоростями 4 и 2 м/с и слипаются. Найди модуль общей скорости.", "answer": 1, "unit": "м/с", "hint": "Выбери одно направление положительным.", "steps": ["p = 1 × 4 − 1 × 2 = 2.", "Общая масса 2 кг, скорость 1 м/с."]}]}, {"grade": 9, "name": "Механическая энергия", "section": "Энергия", "intro": "Кинетическая энергия связана с движением, потенциальная — с положением в поле или деформацией. При отсутствии потерь их сумма сохраняется.", "rules": ["E_k = mv²/2.", "E_p = mgh.", "Для пружины E = kx²/2."], "mistake": "Нулевой уровень потенциальной энергии выбирают, а изменения от выбора не зависят.", "problems": [{"question": "Тело 2 кг движется со скоростью 4 м/с. Найди кинетическую энергию.", "answer": 16, "unit": "Дж", "hint": "Не забудь квадрат скорости и деление на 2.", "steps": ["E = 2 × 16/2 = 16 Дж."]}, {"question": "Тело падает без потерь с высоты 5 м. Найди скорость у земли. g = 10 м/с².", "answer": 10, "unit": "м/с", "hint": "mgh = mv²/2.", "steps": ["v = √(2gh) = √100 = 10 м/с."]}, {"question": "Пружина жёсткостью 200 Н/м сжата на 0,1 м. Она сообщает энергию телу 0,5 кг без потерь. Найди скорость тела.", "answer": 2, "unit": "м/с", "hint": "Энергия пружины превращается в кинетическую.", "steps": ["E = 200 × 0,01/2 = 1 Дж.", "v = √(2E/m) = √4 = 2 м/с."]}]}, {"grade": 9, "name": "Колебания и волны", "section": "Колебания", "intro": "Период — время одного полного колебания, частота — число колебаний в секунду. Волна переносит энергию, а частицы среды колеблются около положения равновесия.", "rules": ["f = 1/T.", "v = λf.", "Для малого маятника T = 2π√(l/g)."], "mistake": "Скорость распространения волны не равна скорости частицы среды.", "problems": [{"question": "За 10 с произошло 20 колебаний. Найди частоту.", "answer": 2, "unit": "Гц", "hint": "Частота — число колебаний, делённое на время.", "steps": ["f = 20/10 = 2 Гц."]}, {"question": "Скорость волны 12 м/с, частота 3 Гц. Найди длину волны.", "answer": 4, "unit": "м", "hint": "λ = v/f.", "steps": ["λ = 12/3 = 4 м."]}, {"question": "Длину математического маятника увеличили в 4 раза. Во сколько раз вырос период малых колебаний?", "answer": 2, "unit": "раз", "hint": "Период пропорционален квадратному корню из длины.", "steps": ["T новое / T старое = √4 = 2."]}]}, {"grade": 9, "name": "Звук", "section": "Колебания", "intro": "Звук — механическая волна. Для эха волна проходит путь до препятствия и обратно. Высота тона связана с частотой, громкость — с амплитудой и условиями восприятия.", "rules": ["В воздухе в этих задачах v = 340 м/с.", "При эхе расстояние до препятствия s = vt/2.", "λ = v/f."], "mistake": "Время эха соответствует двойному расстоянию.", "problems": [{"question": "Звук частотой 170 Гц распространяется со скоростью 340 м/с. Найди длину волны.", "answer": 2, "unit": "м", "hint": "λ = v/f.", "steps": ["λ = 340/170 = 2 м."]}, {"question": "Эхо пришло через 0,6 с. Скорость звука 340 м/с. Найди расстояние до стены.", "answer": 102, "unit": "м", "hint": "Раздели полный путь пополам.", "steps": ["s = 340 × 0,6/2 = 102 м."]}, {"question": "Звук прошёл расстояние 680 м за 2 с. За какое время он пройдёт туда и обратно расстояние до препятствия в 255 м при той же скорости?", "answer": 1.5, "unit": "с", "hint": "Найди скорость, затем удвой новое расстояние.", "steps": ["v = 680/2 = 340 м/с.", "t = 510/340 = 1,5 с."]}]}, {"grade": 9, "name": "Атом и радиоактивность", "section": "Атомная физика", "intro": "Атом состоит из ядра и электронов. Период полураспада — время, за которое в среднем распадается половина исходного числа нестабильных ядер.", "rules": ["Массовое число A = число протонов + число нейтронов.", "Зарядовое число Z = число протонов.", "После n периодов остаётся N₀/2ⁿ."], "mistake": "Полураспад не означает, что все ядра исчезнут через два периода.", "problems": [{"question": "У ядра A = 23 и Z = 11. Найди число нейтронов.", "answer": 12, "unit": "шт", "hint": "Вычти число протонов из массового числа.", "steps": ["N = 23 − 11 = 12."]}, {"question": "Первоначально было 8000 нестабильных ядер. Сколько в среднем останется после трёх периодов полураспада?", "answer": 1000, "unit": "шт", "hint": "Каждый период уменьшает число вдвое.", "steps": ["8000/2³ = 1000."]}, {"question": "Через 12 часов осталось 1/8 исходного числа ядер. Найди период полураспада в часах.", "answer": 4, "unit": "ч", "hint": "1/8 соответствует трём периодам.", "steps": ["3T = 12 ч.", "T = 4 ч."]}]}, {"grade": 10, "name": "Кинематика в двух измерениях", "section": "Механика", "intro": "Независимость движений по осям позволяет разложить полёт на горизонтальную и вертикальную части. Сопротивлением воздуха в этих задачах пренебрегаем.", "rules": ["x = vₓt.", "Для горизонтального броска h = gt²/2.", "v² = vₓ² + vᵧ²."], "mistake": "Горизонтальная скорость не определяет время падения с заданной высоты.", "problems": [{"question": "Тело брошено горизонтально со скоростью 5 м/с. За 2 с какой горизонтальный путь оно пролетит?", "answer": 10, "unit": "м", "hint": "По горизонтали движение равномерное.", "steps": ["x = 5 × 2 = 10 м."]}, {"question": "Тело брошено горизонтально с высоты 20 м со скоростью 8 м/с. Найди дальность при g = 10 м/с².", "answer": 16, "unit": "м", "hint": "Сначала найди время падения.", "steps": ["t = √(40/10) = 2 с.", "x = 8 × 2 = 16 м."]}, {"question": "Тело брошено горизонтально со скоростью 6 м/с. Через 0,8 с найди модуль скорости при g = 10 м/с².", "answer": 10, "unit": "м/с", "hint": "Скорости по осям перпендикулярны.", "steps": ["vᵧ = 10 × 0,8 = 8 м/с.", "v = √(36 + 64) = 10 м/с."]}]}, {"grade": 10, "name": "Динамика систем тел", "section": "Механика", "intro": "Для системы связанных тел полезно записать второй закон Ньютона для каждого тела. В идеальной нити натяжение одинаково, массы блока и нити можно не учитывать только по условию.", "rules": ["Для каждого тела: ΣF = ma.", "У связанных нерастяжимой нитью тел модули ускорений связаны.", "Внутреннее натяжение сокращается в уравнении всей системы."], "mistake": "Не присваивай натяжению значение mg, если груз ускоряется.", "problems": [{"question": "Два связанных тела общей массой 5 кг на гладкой горизонтали тянут силой 20 Н. Найди ускорение.", "answer": 4, "unit": "м/с²", "hint": "Рассматривай тела как систему.", "steps": ["a = 20/5 = 4 м/с²."]}, {"question": "Тело 2 кг на гладком столе связано через идеальный блок с висящим грузом 3 кг. g = 10 м/с². Найди ускорение.", "answer": 6, "unit": "м/с²", "hint": "Движущая внешняя сила 3g, общая масса 5 кг.", "steps": ["a = 30/(2 + 3) = 6 м/с²."]}, {"question": "В машине Атвуда грузы 3 и 2 кг, блок и нить идеальны. g = 10 м/с². Найди натяжение нити.", "answer": 24, "unit": "Н", "hint": "Сначала a = (m₁ − m₂)g/(m₁ + m₂).", "steps": ["a = 10/5 = 2 м/с².", "Для груза 2 кг: T − 20 = 2 × 2.", "T = 24 Н."]}]}, {"grade": 10, "name": "Гравитация и орбиты", "section": "Механика", "intro": "Гравитационная сила между точечными массами убывает как квадрат расстояния. Для круговой орбиты она создаёт центростремительное ускорение.", "rules": ["F = Gm₁m₂/r².", "v = √(GM/r) на круговой орбите.", "g = GM/r²."], "mistake": "Расстояние r считают между центрами масс, а не от поверхности.", "problems": [{"question": "Расстояние между массами увеличили в 3 раза. Во сколько раз уменьшилась сила гравитации?", "answer": 9, "unit": "раз", "hint": "Зависимость обратно квадратичная.", "steps": ["Сила стала в 3² = 9 раз меньше."]}, {"question": "На поверхности планеты g = 16 м/с². Найди g на высоте, равной радиусу планеты.", "answer": 4, "unit": "м/с²", "hint": "Расстояние до центра удвоилось.", "steps": ["g новое = 16/2² = 4 м/с²."]}, {"question": "Радиус круговой орбиты увеличили в 4 раза. Во сколько раз уменьшилась орбитальная скорость?", "answer": 2, "unit": "раз", "hint": "Скорость пропорциональна 1/√r.", "steps": ["Скорость уменьшилась в √4 = 2 раза."]}]}, {"grade": 10, "name": "Молекулярно-кинетическая теория", "section": "Молекулярная физика", "intro": "Давление газа возникает из-за ударов молекул о стенки. Абсолютная температура связана со средней кинетической энергией поступательного движения частиц.", "rules": ["p = nkT.", "Средняя энергия поступательного движения = 3kT/2.", "T(K) = t(°C) + 273 в школьном приближении."], "mistake": "В формулах МКТ используют абсолютную температуру.", "problems": [{"question": "Переведи 27 °C в кельвины, используя прибавление 273.", "answer": 300, "unit": "К", "hint": "Сложи 27 и 273.", "steps": ["T = 300 К."]}, {"question": "При постоянной концентрации температуру газа повысили с 300 до 600 K. Давление было 100 кПа. Найди новое давление.", "answer": 200000, "unit": "Па", "hint": "p пропорционально T.", "steps": ["Температура удвоилась.", "p = 200 кПа = 200000 Па."]}, {"question": "Среднеквадратичная скорость молекул выросла вдвое, концентрация и масса молекулы постоянны. Во сколько раз выросло давление?", "answer": 4, "unit": "раз", "hint": "p пропорционально квадрату скорости.", "steps": ["p новое / p старое = 2² = 4."]}]}, {"grade": 10, "name": "Уравнение состояния газа", "section": "Молекулярная физика", "intro": "Идеальный газ описывается температурой, давлением, объёмом и количеством вещества. Для постоянной массы отношение pV/T сохраняется между состояниями.", "rules": ["pV = νRT.", "p₁V₁/T₁ = p₂V₂/T₂ для постоянного ν.", "В задачах с численным R используй 8,31 Дж/(моль·К)."], "mistake": "Постоянство массы газа — важное условие объединённого газового закона.", "problems": [{"question": "Газ изотермически сжали с 4 до 2 л. Начальное давление 100 кПа. Найди конечное давление.", "answer": 200000, "unit": "Па", "hint": "pV постоянно.", "steps": ["p₂ = 100 × 4/2 = 200 кПа."]}, {"question": "При постоянном давлении газ занимал 2 л при 300 K. Найди объём при 450 K в м³.", "answer": 0.003, "unit": "м³", "hint": "V/T постоянно.", "steps": ["V₂ = 2 × 450/300 = 3 л = 0,003 м³."]}, {"question": "Давление газа выросло в 2 раза, объём в 3 раза. Температура была 200 K, масса постоянна. Найди конечную температуру.", "answer": 1200, "unit": "К", "hint": "T пропорциональна pV.", "steps": ["T₂ = 200 × 2 × 3 = 1200 K."]}]}, {"grade": 10, "name": "Первый закон термодинамики", "section": "Термодинамика", "intro": "Подведённая теплота расходуется на изменение внутренней энергии и работу газа. В этом разделе положительна работа, которую совершает сам газ.", "rules": ["Q = ΔU + A газа.", "Изохорно A = 0.", "Адиабатически Q = 0."], "mistake": "Не смешивай знаки работы газа и работы над газом.", "problems": [{"question": "Газ получил 500 Дж теплоты и совершил работу 200 Дж. Найди изменение внутренней энергии.", "answer": 300, "unit": "Дж", "hint": "ΔU = Q − A.", "steps": ["ΔU = 500 − 200 = 300 Дж."]}, {"question": "Газ адиабатически совершил работу 150 Дж. Найди изменение внутренней энергии.", "answer": -150, "unit": "Дж", "hint": "Теплообмена нет.", "steps": ["ΔU = 0 − 150 = −150 Дж."]}, {"question": "Газ при давлении 100000 Па расширился с 0,002 до 0,005 м³ и получил 800 Дж теплоты. Найди ΔU.", "answer": 500, "unit": "Дж", "hint": "При постоянном давлении A = pΔV.", "steps": ["A = 100000 × 0,003 = 300 Дж.", "ΔU = 800 − 300 = 500 Дж."]}]}, {"grade": 10, "name": "Электростатика", "section": "Электричество", "intro": "Электрическое поле действует на заряд силой. Для точечных зарядов закон Кулона задаёт модуль взаимодействия; знак зарядов определяет притяжение или отталкивание.", "rules": ["F = k|q₁q₂|/r².", "E = F/q для положительного пробного заряда.", "Здесь k = 9 × 10⁹ Н·м²/Кл²."], "mistake": "Поле существует и без помещённого в него пробного заряда.", "problems": [{"question": "На положительный заряд 0,002 Кл действует сила 6 Н. Найди напряжённость поля.", "answer": 3000, "unit": "Н/Кл", "hint": "E = F/q.", "steps": ["E = 6/0,002 = 3000 Н/Кл."]}, {"question": "Два заряда по 1 мкКл находятся на расстоянии 0,3 м в вакууме. k = 9×10⁹. Найди силу.", "answer": 0.1, "unit": "Н", "hint": "1 мкКл = 10⁻⁶ Кл.", "steps": ["F = 9×10⁹ × 10⁻¹² / 0,09 = 0,1 Н."]}, {"question": "Расстояние между зарядами уменьшили вдвое, каждый заряд увеличили в 3 раза. Во сколько раз выросла сила?", "answer": 36, "unit": "раз", "hint": "Учти произведение зарядов и квадрат расстояния.", "steps": ["Коэффициент силы 3 × 3 × 2² = 36."]}]}, {"grade": 10, "name": "Потенциал и конденсаторы", "section": "Электричество", "intro": "Потенциал — потенциальная энергия единичного заряда. Конденсатор накапливает разделённый заряд и энергию электрического поля.", "rules": ["C = q/U.", "W = CU²/2.", "Для однородного поля E = U/d."], "mistake": "Энергия при постоянной ёмкости пропорциональна квадрату напряжения.", "problems": [{"question": "Конденсатор ёмкостью 0,001 Ф подключён к 10 В. Найди заряд.", "answer": 0.01, "unit": "Кл", "hint": "q = CU.", "steps": ["q = 0,001 × 10 = 0,01 Кл."]}, {"question": "Ёмкость 0,002 Ф, напряжение 20 В. Найди запасённую энергию.", "answer": 0.4, "unit": "Дж", "hint": "W = CU²/2.", "steps": ["W = 0,002 × 400/2 = 0,4 Дж."]}, {"question": "Между параллельными пластинами 120 В, расстояние 3 см. Краевыми эффектами пренебречь. Найди напряжённость.", "answer": 4000, "unit": "Н/Кл", "hint": "Переведи расстояние в метры.", "steps": ["E = 120/0,03 = 4000 В/м = 4000 Н/Кл."]}]}, {"grade": 11, "name": "Постоянный ток и ЭДС", "section": "Электродинамика", "intro": "Источник характеризуют ЭДС и внутренним сопротивлением. Часть напряжения теряется внутри источника при протекании тока.", "rules": ["I = ε/(R + r).", "U внешнее = IR = ε − Ir.", "При коротком замыкании I = ε/r в этой модели."], "mistake": "ЭДС не всегда равна напряжению на зажимах работающего источника.", "problems": [{"question": "ЭДС 12 В, внешнее сопротивление 5 Ом, внутреннее 1 Ом. Найди ток.", "answer": 2, "unit": "А", "hint": "Сложи оба сопротивления.", "steps": ["I = 12/6 = 2 А."]}, {"question": "Источник с ЭДС 10 В и внутренним сопротивлением 1 Ом даёт ток 2 А. Найди напряжение на внешней цепи.", "answer": 8, "unit": "В", "hint": "Вычти падение внутри источника.", "steps": ["U = 10 − 2 × 1 = 8 В."]}, {"question": "Источник с ЭДС 12 В и r = 2 Ом подключён к R = 2 Ом. Найди мощность на внешнем резисторе.", "answer": 18, "unit": "Вт", "hint": "Сначала ток всей цепи.", "steps": ["I = 12/4 = 3 А.", "P = I²R = 9 × 2 = 18 Вт."]}]}, {"grade": 11, "name": "Магнитное поле и силы", "section": "Электродинамика", "intro": "Магнитное поле действует на движущиеся заряды и проводники с током. Магнитная сила на заряд перпендикулярна скорости и не меняет кинетическую энергию сама по себе.", "rules": ["F Ампера = BIl sin α.", "F Лоренца = |q|vB sin α.", "При v ⟂ B радиус траектории r = mv/(|q|B)."], "mistake": "Сила зависит от угла между векторами, при параллельности она нулевая.", "problems": [{"question": "Проводник длиной 0,5 м с током 4 А перпендикулярен полю 0,2 Тл. Найди силу Ампера.", "answer": 0.4, "unit": "Н", "hint": "sin 90° = 1.", "steps": ["F = 0,2 × 4 × 0,5 = 0,4 Н."]}, {"question": "Заряд 0,001 Кл движется перпендикулярно полю 0,5 Тл со скоростью 200 м/с. Найди магнитную силу.", "answer": 0.1, "unit": "Н", "hint": "F = qvB.", "steps": ["F = 0,001 × 200 × 0,5 = 0,1 Н."]}, {"question": "Скорость частицы в однородном магнитном поле удвоилась при неизменных массе, заряде и перпендикулярном направлении движения. Во сколько раз вырос радиус окружности?", "answer": 2, "unit": "раз", "hint": "r пропорционален скорости.", "steps": ["r новое / r старое = 2."]}]}, {"grade": 11, "name": "Электромагнитная индукция", "section": "Электродинамика", "intro": "Изменяющийся магнитный поток создаёт ЭДС индукции. Правило Ленца определяет направление, а скорость изменения потока — модуль ЭДС.", "rules": ["Φ = BS cos α, α к нормали.", "|ε| = N|ΔΦ|/Δt при равномерном изменении.", "ЭДС движения стержня ε = Blv при взаимной перпендикулярности."], "mistake": "Угол в формуле потока отсчитывают от нормали к рамке.", "problems": [{"question": "Поток через один виток изменился на 0,6 Вб за 0,2 с. Найди модуль средней ЭДС.", "answer": 3, "unit": "В", "hint": "Подели изменение потока на время.", "steps": ["|ε| = 0,6/0,2 = 3 В."]}, {"question": "Катушка имеет 100 витков. Поток через виток изменился на 0,002 Вб за 0,1 с. Найди модуль средней ЭДС.", "answer": 2, "unit": "В", "hint": "Учти число витков.", "steps": ["|ε| = 100 × 0,002/0,1 = 2 В."]}, {"question": "Стержень длиной 0,5 м движется со скоростью 4 м/с поперёк поля 0,3 Тл; все направления взаимно перпендикулярны. Найди ЭДС.", "answer": 0.6, "unit": "В", "hint": "ε = Blv.", "steps": ["ε = 0,3 × 0,5 × 4 = 0,6 В."]}]}, {"grade": 11, "name": "Электромагнитные колебания и волны", "section": "Колебания", "intro": "В идеальном LC-контуре энергия переходит между электрическим полем конденсатора и магнитным полем катушки. Электромагнитная волна может распространяться в вакууме.", "rules": ["T = 2π√(LC).", "c = λf, c = 3 × 10⁸ м/с.", "Для идеального трансформатора U₂/U₁ = N₂/N₁."], "mistake": "В трансформаторе изменение напряжения сопровождается изменением тока, энергия не возникает из ничего.", "problems": [{"question": "Радиоволна имеет частоту 100 МГц. Найди длину волны в вакууме.", "answer": 3, "unit": "м", "hint": "100 МГц = 10⁸ Гц.", "steps": ["λ = 3×10⁸/10⁸ = 3 м."]}, {"question": "В идеальном трансформаторе N₁ = 1000, N₂ = 100, U₁ = 220 В. Найди U₂.", "answer": 22, "unit": "В", "hint": "Используй отношение витков.", "steps": ["U₂ = 220 × 100/1000 = 22 В."]}, {"question": "Ёмкость LC-контура увеличили в 9 раз при постоянной индуктивности. Во сколько раз уменьшилась собственная частота?", "answer": 3, "unit": "раз", "hint": "Частота обратно пропорциональна √C.", "steps": ["f уменьшится в √9 = 3 раза."]}]}, {"grade": 11, "name": "Геометрическая оптика и линзы", "section": "Оптика", "intro": "Линза изменяет направление световых лучей. Для действительных предмета и изображения в задачах на собирающую линзу удобно использовать положительные расстояния.", "rules": ["1/F = 1/a + 1/b для действительного изображения.", "D = 1/F, где F в метрах.", "Модуль увеличения Γ = b/a."], "mistake": "Для мнимых изображений нужна согласованная система знаков; здесь условия явно задают действительное изображение.", "problems": [{"question": "Фокусное расстояние собирающей линзы 0,2 м. Найди оптическую силу.", "answer": 5, "unit": "дптр", "hint": "D = 1/F.", "steps": ["D = 1/0,2 = 5 дптр."]}, {"question": "Предмет находится в 0,3 м от собирающей линзы с F = 0,1 м. Найди расстояние до действительного изображения.", "answer": 0.15, "unit": "м", "hint": "Вырази 1/b.", "steps": ["1/b = 10 − 1/0,3 = 20/3.", "b = 0,15 м."]}, {"question": "Действительное изображение в 3 раза больше предмета. Фокусное расстояние собирающей линзы 0,12 м. Найди расстояние до предмета.", "answer": 0.16, "unit": "м", "hint": "Положи b = 3a.", "steps": ["1/F = 1/a + 1/(3a) = 4/(3a).", "a = 4F/3 = 0,16 м."]}]}, {"grade": 11, "name": "Интерференция и дифракция", "section": "Оптика", "intro": "При наложении когерентных волн интенсивность зависит от разности фаз. Дифракционная решётка разделяет свет по длинам волн.", "rules": ["Максимум при разности хода Δ = mλ.", "Для решётки d sin θ = mλ.", "Частота света при переходе в другую среду сохраняется."], "mistake": "Для устойчивой интерференционной картины нужны согласованные по частоте и фазе волны.", "problems": [{"question": "Разность хода равна двум длинам волны. Какой порядок интерференционного максимума?", "answer": 2, "unit": "шт", "hint": "Δ = mλ.", "steps": ["m = Δ/λ = 2."]}, {"question": "Период решётки 2 мкм, длина волны 0,5 мкм. Найди sin угла максимума первого порядка.", "answer": 0.25, "unit": "безразм.", "hint": "sin θ = λ/d.", "steps": ["sin θ = 0,5/2 = 0,25."]}, {"question": "Период решётки 2 мкм, длина волны 0,6 мкм. Найди наибольший возможный целый порядок максимума.", "answer": 3, "unit": "шт", "hint": "Модуль синуса не превышает 1.", "steps": ["m ≤ d/λ = 2/0,6 ≈ 3,33.", "Наибольшее целое m = 3."]}]}, {"grade": 11, "name": "Фотоны и фотоэффект", "section": "Квантовая физика", "intro": "Энергия света передаётся квантами — фотонами. При фотоэффекте энергия фотона расходуется на работу выхода и кинетическую энергию электрона.", "rules": ["E = hf.", "E фотона = A выхода + E_k max.", "В задачах в электронвольтах обе энергии должны быть в эВ."], "mistake": "Увеличение интенсивности при прежней частоте не увеличивает энергию отдельного фотона.", "problems": [{"question": "Энергия фотона 5 эВ, работа выхода 2 эВ. Найди максимальную кинетическую энергию электрона.", "answer": 3, "unit": "эВ", "hint": "Вычти работу выхода.", "steps": ["E_k = 5 − 2 = 3 эВ."]}, {"question": "Энергия фотона была 2 эВ. Частоту увеличили втрое. Найди новую энергию.", "answer": 6, "unit": "эВ", "hint": "Энергия пропорциональна частоте.", "steps": ["E = 2 × 3 = 6 эВ."]}, {"question": "Фотоэлектроны имеют максимальную энергию 4 эВ. Работа выхода металла 3 эВ. Найди энергию падающего фотона.", "answer": 7, "unit": "эВ", "hint": "Сложи работу выхода и кинетическую энергию.", "steps": ["E = 3 + 4 = 7 эВ."]}]}, {"grade": 11, "name": "Ядерные превращения и энергия", "section": "Ядерная физика", "intro": "В ядерных реакциях сохраняются электрический заряд и число нуклонов. Изменение массы связано с выделенной или поглощённой энергией.", "rules": ["E = Δmc².", "При α-распаде A уменьшается на 4, Z на 2.", "При β⁻-распаде A постоянно, Z растёт на 1."], "mistake": "Массовое число — число нуклонов, а не масса атома в килограммах.", "problems": [{"question": "Ядро с A = 238 испускает α-частицу. Найди массовое число дочернего ядра.", "answer": 234, "unit": "шт", "hint": "Альфа-частица содержит четыре нуклона.", "steps": ["A новое = 238 − 4 = 234."]}, {"question": "Ядро с Z = 6 испытывает β⁻-распад. Найди новое зарядовое число.", "answer": 7, "unit": "шт", "hint": "Нейтрон превращается в протон.", "steps": ["Z новое = 6 + 1 = 7."]}, {"question": "Дефект массы реакции равен 0,002 кг. c = 3×10⁸ м/с. Найди выделившуюся энергию.", "answer": 180000000000000.0, "unit": "Дж", "hint": "Возведи скорость света в квадрат.", "steps": ["E = 0,002 × 9×10¹⁶ = 1,8×10¹⁴ Дж."]}]}];

