function physicsNumber(raw){const s=raw.trim().replaceAll('−','-').replace(',','.');return /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(s)?Number(s):parseAnswer(s)}
function physicsAccept(actual,expected){return Number.isFinite(actual)&&Math.abs(actual-expected)<=Math.max(Math.abs(expected)*.001,1e-30)}
